// @ts-check
// A tiny RGB canvas for the summary card: rectangles, alpha masks and text from the
// pre-rendered glyphs in glyphs.js (generated by scripts/card/build-assets.mjs).
// Pure (no SDK): tests and the Mini App use it too.

import { FONTS } from './glyphs.js';

/** @typedef {[number, number, number]} Rgb */
/** @typedef {keyof typeof FONTS} FontName */

/** "#rrggbb" → [r, g, b]. @param {string} hex @returns {Rgb} */
export function rgb(hex) {
  const v = parseInt(hex.slice(1), 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_INDEX = new Uint8Array(128);
for (let i = 0; i < B64.length; i++) B64_INDEX[B64.charCodeAt(i)] = i;

/** Base64 → bytes, without relying on atob or Buffer. @param {string} s */
export function fromBase64(s) {
  const len = s.length;
  const pad = s.endsWith('==') ? 2 : s.endsWith('=') ? 1 : 0;
  const out = new Uint8Array((len / 4) * 3 - pad);
  for (let i = 0, o = 0; i < len; i += 4) {
    const n =
      (B64_INDEX[s.charCodeAt(i)] << 18) |
      (B64_INDEX[s.charCodeAt(i + 1)] << 12) |
      (B64_INDEX[s.charCodeAt(i + 2)] << 6) |
      B64_INDEX[s.charCodeAt(i + 3)];
    out[o++] = n >> 16;
    if (o < out.length) out[o++] = (n >> 8) & 255;
    if (o < out.length) out[o++] = n & 255;
  }
  return out;
}

/**
 * Decode a run-length mask (format in scripts/card/build-assets.mjs) into 8-bit alpha.
 * @param {Uint8Array} bytes @param {number} at offset of the first run @param {number} count pixels
 */
export function decodeMask(bytes, at, count) {
  const out = new Uint8Array(count);
  for (let o = 0; o < count; ) {
    const b = bytes[at++];
    const level = (b >> 4) * 17;
    let run = (b & 15) + 1;
    if (run === 16) {
      let v = 0;
      let shift = 0;
      let next;
      do {
        next = bytes[at++];
        v |= (next & 0x7f) << shift;
        shift += 7;
      } while (next & 0x80);
      run = 16 + v;
    }
    if (level) out.fill(level, o, o + run);
    o += run;
  }
  return out;
}

/** @typedef {{ advance: number, x: number, y: number, w: number, h: number, alpha: Uint8Array }} Glyph */

/** @type {Map<string, { size: number, cap: number, glyphs: Map<string, Glyph> }>} */
const fontCache = new Map();

/** Decoded once per font, on first use. @param {FontName} name */
export function font(name) {
  let f = fontCache.get(name);
  if (!f) {
    const src = FONTS[name];
    const bytes = fromBase64(src.data);
    const glyphs = new Map();
    for (const [ch, advance, x, y, w, h, offset] of /** @type {any[]} */ (src.glyphs)) {
      glyphs.set(ch, { advance, x, y, w, h, alpha: decodeMask(bytes, offset, w * h) });
    }
    f = { size: src.size, cap: src.cap, glyphs };
    fontCache.set(name, f);
  }
  return f;
}

/** A glyph's advance; a character the atlas lacks takes half an em. @param {ReturnType<typeof font>} f @param {string} ch */
const advanceOf = (f, ch) => f.glyphs.get(ch)?.advance ?? f.size * 0.5;

export class Canvas {
  /** Starts black; callers paint the background first. @param {number} width @param {number} height */
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.data = new Uint8Array(width * height * 3);
  }

  /** @param {number} x @param {number} y @param {number} w @param {number} h @param {Rgb} color */
  fillRect(x, y, w, h, color) {
    const x0 = Math.max(0, Math.round(x));
    const y0 = Math.max(0, Math.round(y));
    const x1 = Math.min(this.width, Math.round(x + w));
    const y1 = Math.min(this.height, Math.round(y + h));
    for (let yy = y0; yy < y1; yy++) {
      for (let xx = x0, i = (yy * this.width + x0) * 3; xx < x1; xx++, i += 3) {
        this.data[i] = color[0];
        this.data[i + 1] = color[1];
        this.data[i + 2] = color[2];
      }
    }
  }

  /** Blend one pixel. @param {number} x @param {number} y @param {Rgb} color @param {number} a 0–255 */
  blend(x, y, color, a) {
    this.blendRgb(x, y, color[0], color[1], color[2], a);
  }

  /** `blend` with the colour as separate channels, for loops that would otherwise build arrays. */
  blendRgb(/** @type {number} */ x, /** @type {number} */ y, /** @type {number} */ r, /** @type {number} */ g, /** @type {number} */ b, /** @type {number} */ a) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height || a <= 0) return;
    const d = this.data;
    const i = (y * this.width + x) * 3;
    if (a >= 255) {
      d[i] = r;
      d[i + 1] = g;
      d[i + 2] = b;
      return;
    }
    d[i] += ((r - d[i]) * a) / 255;
    d[i + 1] += ((g - d[i + 1]) * a) / 255;
    d[i + 2] += ((b - d[i + 2]) * a) / 255;
  }

  /**
   * Rounded rectangle, anti-aliased onto what's underneath. `radii` = [top-left, top-right,
   * bottom-right, bottom-left]. Coordinates are whole pixels.
   * @param {number} x @param {number} y @param {number} w @param {number} h
   * @param {number | [number, number, number, number]} radii @param {Rgb} color
   */
  fillRoundRect(x, y, w, h, radii, color) {
    const [tl, tr, br, bl] = typeof radii === 'number' ? [radii, radii, radii, radii] : radii;
    for (let yy = y; yy < y + h; yy++) {
      for (let xx = x; xx < x + w; xx++) {
        const px = xx + 0.5;
        const py = yy + 0.5;
        let r = 0;
        let cx = 0;
        let cy = 0;
        if (px < x + tl && py < y + tl) (r = tl), (cx = x + tl), (cy = y + tl);
        else if (px > x + w - tr && py < y + tr) (r = tr), (cx = x + w - tr), (cy = y + tr);
        else if (px > x + w - br && py > y + h - br) (r = br), (cx = x + w - br), (cy = y + h - br);
        else if (px < x + bl && py > y + h - bl) (r = bl), (cx = x + bl), (cy = y + h - bl);
        const cover = r ? Math.max(0, Math.min(1, r - Math.hypot(px - cx, py - cy) + 0.5)) : 1;
        if (cover > 0) this.blend(xx, yy, color, Math.round(cover * 255));
      }
    }
  }

  /**
   * A line from (x0, y0) to (x1, y1), `width` thick with round ends, anti-aliased. `color` may
   * be a function of x, for bars whose colour changes along their length.
   * @param {number} x0 @param {number} y0 @param {number} x1 @param {number} y1 @param {number} width
   * @param {Rgb | ((x: number) => Rgb)} color
   */
  fillSegment(x0, y0, x1, y1, width, color) {
    const r = width / 2;
    const dx = x1 - x0;
    const dy = y1 - y0;
    const len2 = dx * dx + dy * dy || 1;
    const colorAt = typeof color === 'function' ? color : () => color;
    for (let y = Math.floor(Math.min(y0, y1) - r); y < Math.ceil(Math.max(y0, y1) + r); y++) {
      for (let x = Math.floor(Math.min(x0, x1) - r); x < Math.ceil(Math.max(x0, x1) + r); x++) {
        const px = x + 0.5;
        const py = y + 0.5;
        const t = Math.max(0, Math.min(1, ((px - x0) * dx + (py - y0) * dy) / len2));
        const cover = r - Math.hypot(px - x0 - t * dx, py - y0 - t * dy) + 0.5;
        if (cover > 0) this.blend(x, y, colorAt(px), Math.round(Math.min(1, cover) * 255));
      }
    }
  }

  /**
   * A stretch of a ring around (cx, cy), anti-aliased, with square ends. Angles in radians,
   * counter-clockwise from 3 o'clock (y up), `a0` < `a1`, within the top half plus a little.
   * @param {number} cx @param {number} cy @param {number} rIn @param {number} rOut @param {number} a0 @param {number} a1 @param {Rgb} color
   */
  fillArc(cx, cy, rIn, rOut, a0, a1, color) {
    for (let y = Math.floor(cy - rOut); y < Math.ceil(cy + rOut * 0.2); y++) {
      for (let x = Math.floor(cx - rOut); x < Math.ceil(cx + rOut); x++) {
        const dx = x + 0.5 - cx;
        const dy = cy - (y + 0.5);
        const r = Math.hypot(dx, dy);
        let a = Math.atan2(dy, dx);
        if (a < -Math.PI / 2) a += 2 * Math.PI;
        const clamp = (/** @type {number} */ v) => Math.max(0, Math.min(1, v + 0.5));
        const cover = clamp(r - rIn) * clamp(rOut - r) * clamp((a - a0) * r) * clamp((a1 - a) * r);
        if (cover > 0) this.blend(x, y, color, Math.round(cover * 255));
      }
    }
  }

  /** Fill the whole canvas with a top-to-bottom gradient. @param {Rgb} top @param {Rgb} bottom */
  verticalGradient(top, bottom) {
    for (let y = 0; y < this.height; y++) {
      const t = y / (this.height - 1);
      /** @type {Rgb} */
      const c = [0, 0, 0];
      for (let i = 0; i < 3; i++) c[i] = Math.round(top[i] + (bottom[i] - top[i]) * t);
      this.fillRect(0, y, this.width, 1, c);
    }
  }

  /**
   * An elliptical glow: `alpha` (0–1) of `color` at the centre, fading linearly to nothing at
   * `fade` of the radii (like CSS `radial-gradient(… color, transparent fade%)`).
   * @param {number} cx @param {number} cy @param {number} rx @param {number} ry @param {Rgb} color @param {number} alpha @param {number} fade
   */
  glow(cx, cy, rx, ry, color, alpha, fade) {
    // Only the ellipse's bounding box can be lit.
    const y0 = Math.max(0, Math.floor(cy - ry * fade));
    const y1 = Math.min(this.height, Math.ceil(cy + ry * fade));
    const x0 = Math.max(0, Math.floor(cx - rx * fade));
    const x1 = Math.min(this.width, Math.ceil(cx + rx * fade));
    const f2 = fade * fade;
    for (let y = y0; y < y1; y++) {
      const dy = (y + 0.5 - cy) / ry;
      for (let x = x0; x < x1; x++) {
        const dx = (x + 0.5 - cx) / rx;
        const d2 = dx * dx + dy * dy;
        if (d2 < f2) this.blend(x, y, color, Math.round((1 - Math.sqrt(d2) / fade) * alpha * 255));
      }
    }
  }

  /** Draw straight (non-premultiplied) RGBA pixels. @param {Uint8Array} rgba @param {number} w @param {number} h @param {number} x @param {number} y */
  blitRgba(rgba, w, h, x, y) {
    for (let yy = 0; yy < h; yy++) {
      for (let xx = 0; xx < w; xx++) {
        const i = (yy * w + xx) * 4;
        if (rgba[i + 3]) this.blendRgb(x + xx, y + yy, rgba[i], rgba[i + 1], rgba[i + 2], rgba[i + 3]);
      }
    }
  }

  /**
   * Draw an 8-bit alpha mask in `color`, scaled by `opacity`.
   * @param {Uint8Array} alpha @param {number} w @param {number} h @param {number} x @param {number} y @param {Rgb} color @param {number} [opacity]
   */
  blitMask(alpha, w, h, x, y, color, opacity = 1) {
    for (let yy = 0; yy < h; yy++) {
      for (let xx = 0; xx < w; xx++) {
        const a = alpha[yy * w + xx];
        if (a) this.blend(x + xx, y + yy, color, opacity === 1 ? a : Math.round(a * opacity));
      }
    }
  }

  /** @param {string} text @param {FontName} fontName */
  measure(text, fontName) {
    const f = font(fontName);
    let w = 0;
    for (const ch of text) w += advanceOf(f, ch);
    return w;
  }

  /**
   * Text on a baseline. `align` positions `x` at the left, centre or right of the advance box.
   * @param {string} text @param {number} x @param {number} baseline @param {FontName} fontName @param {Rgb} color
   * @param {'left' | 'center' | 'right'} [align]
   */
  text(text, x, baseline, fontName, color, align = 'left') {
    const f = font(fontName);
    let pen = align === 'left' ? x : x - this.measure(text, fontName) / (align === 'center' ? 2 : 1);
    for (const ch of text) {
      const g = f.glyphs.get(ch);
      if (g?.w) this.blitMask(g.alpha, g.w, g.h, Math.round(pen + g.x), Math.round(baseline + g.y), color);
      pen += advanceOf(f, ch);
    }
  }

  /** Cap height in px, for centring text vertically. @param {FontName} fontName */
  capHeight(fontName) {
    return font(fontName).cap;
  }
}
